package com.bananalab.lite;
import android.content.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.regex.*;import org.json.*;
/** Edits a copy of a real application method, then dispatches the verified compiled replacement. */
final class JavaMethodEditor{
 static volatile Method active;static int loaded=-1;
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-java-method",0);}
 static String base(Context c)throws Exception{return AppJavaChat.asset(c,"java-edit-base/ChatLanguage.java",30000);}
 static String storedSource(JSONObject row)throws Exception{try(InputStream in=new FileInputStream(new File(row.getString("sourceFile")))){return new String(OnDeviceJava.bytes(in,40000),"UTF-8");}}
 static Method method(Context c,String path)throws Exception{return OnDeviceJava.load(c,new File(path)).getClassLoader().loadClass("com.bananalab.patch.ChatLanguagePatched").getMethod("socialReply",String.class);}
 static String hash(String value)throws Exception{byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes("UTF-8"));StringBuilder out=new StringBuilder();for(byte b:bytes)out.append(Integer.toHexString((b&255)|256).substring(1));return out.toString();}
 static String social(String input)throws Exception{return (String)active.invoke(null,input);}
 static int check(Method method,JavaTextPlan plan)throws Exception{plan.controls();String[] samples=plan.samples();for(String input:samples){Object got=method.invoke(null,new String(input));String wanted=plan.expected(input);if(!Objects.equals(got,wanted))throw new IOException("Resultado incorrecto para la prueba: "+input);}return samples.length;}
 static JavaTextPlan current(Context c)throws Exception{String raw=prefs(c).getString("active","");return raw.isEmpty()?new JavaTextPlan():JavaTextPlan.read(new JSONObject(raw).getString("plan"));}
 static synchronized void restore(Context c){int revision=prefs(c).getInt("revision",0);if(loaded==revision)return;try{String raw=prefs(c).getString("active","");Method m=null;if(!raw.isEmpty()){JSONObject row=new JSONObject(raw);JavaTextPlan plan=JavaTextPlan.read(row.getString("plan"));if(!row.getString("source").equals(plan.edited(base(c)))||!row.getString("source").equals(storedSource(row)))throw new IOException("La base del archivo cambió.");m=method(c,row.getString("jar"));check(m,plan);}active=m;loaded=revision;}catch(Throwable e){active=null;loaded=revision;prefs(c).edit().putString("error","Usé el método original: "+e.getClass().getSimpleName()).apply();}}
 static synchronized String prepare(Context c,JavaTextPlan plan)throws Exception{plan.controls();String original=base(c),before=prefs(c).getString("active",""),edited=plan.edited(original);int rev=prefs(c).getInt("revision",0);File sourceDir=new File(c.getDir("java-method-source",0),UUID.randomUUID().toString());if(!sourceDir.mkdirs())throw new IOException("No pude crear la copia de trabajo.");File sourceFile=new File(sourceDir,"ChatLanguage.java");OnDeviceJava.immutable(sourceFile,edited.getBytes("UTF-8"));Map<String,String> files=new LinkedHashMap<>();files.put("BananaBehavior.java",JavaPatchPolicy.BASE);files.put("ChatLanguagePatched.java",plan.compiled(original));JavaChat.phase("Compilando la copia editada del método del chat…");OnDeviceJava.Build build=OnDeviceJava.compileSources(c,files);JavaChat.phase("Comprobando las respuestas en otro proceso…");android.os.Bundle proof=JavaTrial.text(c,build.jar,plan.json().toString(),plan.samples().length);JSONObject draft=new JSONObject().put("plan",plan.json().toString()).put("source",edited).put("sourceFile",sourceFile.getAbsolutePath()).put("jar",build.jar.getAbsolutePath()).put("base",rev).put("priorHash",hash(before)).put("beforeSource",before.isEmpty()?original:new JSONObject(before).getString("source")).put("tests",proof.getInt("samples")).put("pid",proof.getInt("pid"));if(rev!=prefs(c).getInt("revision",0)||!before.equals(prefs(c).getString("active","")))throw new IOException("Cambió la versión durante la compilación.");if(!prefs(c).edit().putString("draft",draft.toString()).commit())throw new IOException("No pude guardar el candidato.");return "Edité una copia de ChatLanguage.java → socialReply. Compiló y pasó "+proof.getInt("samples")+" pruebas en otro proceso.\nTodavía no está activo. Decí ‘mostrame el cambio de java’, ‘aplica el cambio del metodo’ o ‘descarta el cambio del metodo’.";}
 static JSONArray history(Context c)throws Exception{return new JSONArray(prefs(c).getString("history","[]"));}
 static JSONArray archive(Context c)throws Exception{JSONArray old=history(c),next=new JSONArray();for(int i=Math.max(0,old.length()-7);i<old.length();i++)next.put(old.getJSONObject(i));next.put(new JSONObject().put("revision",prefs(c).getInt("revision",0)).put("active",prefs(c).getString("active","")));return next;}
 static synchronized String apply(Context c)throws Exception{String raw=prefs(c).getString("draft","");if(raw.isEmpty())return "No hay un método pendiente de activar.";JSONObject row=new JSONObject(raw);int rev=prefs(c).getInt("revision",0);if(rev!=row.getInt("base")||!row.getString("priorHash").equals(hash(prefs(c).getString("active",""))))throw new IOException("El candidato quedó desactualizado; prepará otro cambio.");JavaTextPlan p=JavaTextPlan.read(row.getString("plan"));if(!p.edited(base(c)).equals(row.getString("source"))||!row.getString("source").equals(storedSource(row)))throw new IOException("La fuente cambió después de la prueba.");JavaTrial.text(c,new File(row.getString("jar")),p.json().toString(),p.samples().length);Method m=method(c,row.getString("jar"));check(m,p);if(!prefs(c).edit().putString("history",archive(c).toString()).putString("active",raw).putInt("revision",rev+1).putLong("changedAt",System.currentTimeMillis()).remove("draft").remove("error").commit())throw new IOException("No pude activar el método.");active=m;loaded=rev+1;AndroidRepair.applied(c,raw);return "Listo. El método editado del chat está activo. Probá una de las frases que elegiste. Para volver: ‘deshace el cambio del metodo’.";}
 static synchronized String recover(Context c,int id)throws Exception{JSONArray h=history(c);JSONObject found=null;for(int i=h.length()-1;i>=0;i--)if(h.getJSONObject(i).getInt("revision")==id){found=h.getJSONObject(i);break;}if(found==null)return "Esa versión no figura en el historial del método.";String raw=found.getString("active");Method m=null;if(!raw.isEmpty()){JSONObject row=new JSONObject(raw);JavaTextPlan p=JavaTextPlan.read(row.getString("plan"));if(!row.getString("source").equals(p.edited(base(c)))||!row.getString("source").equals(storedSource(row)))throw new IOException("Cambió la base del método.");JavaTrial.text(c,new File(row.getString("jar")),p.json().toString(),p.samples().length);m=method(c,row.getString("jar"));check(m,p);}int rev=prefs(c).getInt("revision",0);if(!prefs(c).edit().putString("history",archive(c).toString()).putString("active",raw).putInt("revision",rev+1).putLong("changedAt",System.currentTimeMillis()).remove("draft").remove("error").commit())throw new IOException("No pude recuperar el método.");active=m;loaded=rev+1;return "Recuperé la versión "+id+" del método del chat. Conservé tus mensajes, escenas y personajes.";}
 static String candidate(Context c){return prefs(c).getString("draft",prefs(c).getString("active",""));}
 static String diff(Context c)throws Exception{String raw=candidate(c);if(raw.isEmpty())return "No hay cambios del método para mostrar.";JSONObject row=new JSONObject(raw);String before=row.getString("beforeSource"),after=row.getString("source");int[] a=JavaTextPlan.span(before),b=JavaTextPlan.span(after);return "ChatLanguage.java · socialReply(String message)\n"+(prefs(c).contains("draft")?"Candidato probado, sin activar":"Versión activa")+"\nANTES:\n"+before.substring(a[0],a[1])+"\nDESPUÉS:\n"+after.substring(b[0],b[1])+"\nSólo este método tiene un puente de ejecución; no se reemplazó todo el APK.";}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String q=ChatLanguage.normalize(input);JavaTextPlan plan=null;
  if(q.matches("como edito un metodo java|editor de metodos java"))return MobileCore.say(c,"Podés editar el método real del chat:\ncambia el metodo del chat: cuando diga \"buenas banana\" responde \"Buenas, ¿qué creamos hoy?\"\nTambién: cuando empiece con / cuando termine con / cuando contenga.\nDespués: ‘mostrame el cambio de java’, ‘aplica el cambio del metodo’ o ‘descarta el cambio del metodo’.\nPara escribir el cuerpo: reescribe el metodo del chat: if (text.equals(\"hola\")) return \"Buenas\"; return null;\nUsá ‘versiones del metodo java’ y ‘deshace el cambio del metodo’.\nAlcance: socialReply de ChatLanguage.java, condiciones de texto y respuestas literales. Se compila una copia y se conecta con un puente; no Java general ni reemplazo de clases ya cargadas del APK.","app_ajuste");
  if(q.equals("mostrame el cambio de java"))return MobileCore.say(c,diff(c),"app_ajuste");
  if(q.equals("mostrame el archivo java editado")){String raw=candidate(c);return MobileCore.say(c,raw.isEmpty()?base(c):new JSONObject(raw).getString("source"),"app_ajuste");}
  if(q.equals("versiones del metodo java")){StringBuilder out=new StringBuilder("Método del chat · versión "+prefs(c).getInt("revision",0));JSONArray h=history(c);for(int i=h.length()-1;i>=0;i--)out.append("\nAnterior: ").append(h.getJSONObject(i).getInt("revision"));return MobileCore.say(c,out+"\nPara recuperar: volve a la version 0 del metodo java.","app_ajuste");}
  if(q.equals("descarta el cambio del metodo")){if(!prefs(c).edit().remove("draft").commit())throw new IOException("No pude descartar el candidato.");return MobileCore.say(c,"Descarté el candidato; el método activo se conserva.","app_ajuste");}
  int operation=0;Matcher recover=Pattern.compile("volve a la version ([0-9]{1,9}) del metodo java").matcher(q);
  boolean generic=q.matches("deshace ese ajuste|deshace el ultimo ajuste de la app|volve al funcionamiento anterior")&&prefs(c).getLong("changedAt",0)>Math.max(JavaFunction.prefs(c).getLong("changedAt",0),Math.max(AppJavaWorkspace.prefs(c).getLong("changedAt",0),JavaLive.prefs(c).getLong("changedAt",0)));
  if(q.equals("aplica el cambio del metodo"))operation=1;else if(q.equals("deshace el cambio del metodo")||generic)operation=2;else if(recover.matches())operation=3;
  boolean editing=q.startsWith("cambia el metodo del chat")||q.startsWith("reescribe el metodo del chat");if(operation==0&&!editing)return null;if(editing)prefs(c).edit().putString("lastInput",input.substring(0,Math.min(6000,input.length()))).apply();
  JavaChat.owner=Thread.currentThread();try{String text;if(operation==1)text=apply(c);else if(operation==2){JSONArray h=history(c);text=h.length()==0?"No hay un método anterior.":recover(c,h.getJSONObject(h.length()-1).getInt("revision"));}else if(operation==3)text=recover(c,Integer.parseInt(recover.group(1)));else{int colon=input.indexOf(':');if(colon<0)throw new IllegalArgumentException("Separá la instrucción con dos puntos; pedí ‘como edito un metodo java’ para ver ejemplos.");String prefix=ChatLanguage.normalize(input.substring(0,colon));String body=input.substring(colon+1).trim();if(prefix.equals("reescribe el metodo del chat"))plan=JavaTextPlan.raw(body);else if(prefix.equals("cambia el metodo del chat")){Matcher m=Pattern.compile("(?isu)^cuando (diga|empiece con|termine con|contenga) ("+JavaTextPlan.LIT+") responde ("+JavaTextPlan.LIT+")$").matcher(body);if(!m.matches())throw new IllegalArgumentException("No entendí el cambio completo. Usá cuando diga/empiece con/termine con/contenga, seguido de una frase y una respuesta entre comillas.");plan=current(c);String op=m.group(1).toLowerCase(Locale.ROOT);plan.add(op.equals("diga")?"equals":op.equals("empiece con")?"startsWith":op.equals("termine con")?"endsWith":"contains",JavaTextPlan.decode(m.group(2)),JavaTextPlan.decode(m.group(3)));}else throw new IllegalArgumentException("Hay instrucciones adicionales antes de los dos puntos; no apliqué un cambio parcial.");text=prepare(c,plan);}return MobileCore.say(c,text,"app_ajuste");}catch(Throwable e){prefs(c).edit().putString("error",e.getClass().getSimpleName()+": "+e.getMessage()).apply();return MobileCore.say(c,"No activé un método nuevo. El funcionamiento anterior se conserva.\n"+e.getMessage(),"app_ajuste");}finally{JavaChat.owner=null;JavaChat.progress="";}
 }
}
